import {FURNITURE_BY_ID,houseDescriptor,ROOM} from './housing-data.js?v=20261011-life82';
import {livingKind,livingPose,rhythm,chessStart,chessMove} from './living-shared.js?v=20261011-life82';
// No physics loop: machines advance from server timestamps; clients send intentions.
export class LivingStore{
 constructor(rules){this.rules=rules;this.records=rules.settings.living||{};this.runs=new Map();this.queue=Promise.resolve();}
 snapshot(){return Object.values(this.records);}
 target(entry,m){const p=entry.player,h=houseDescriptor(m.index,this.rules.houses.realms),item=this.rules.houses.snapshots()[m.index]?.items.find(i=>i.id===m.itemId),def=item&&FURNITURE_BY_ID.get(item.t);if(!h||!def||p.ragdoll||p.flight||this.rules.duel?.ids.includes(p.id)||this.rules.guns.members.has(p.id))return null;const pose=livingPose(h.index,item);if(Math.abs(p.x-h.x)>ROOM.x||Math.abs(p.z-h.z)>ROOM.z||Math.hypot(p.x-pose.x,p.z-pose.z)>4||Math.abs(p.y+1-pose.y)>3)return null;return {h,item,def,pose,kind:livingKind(def),key:h.index+':'+item.id};}
 receive(entry,m){this.queue=this.queue.then(()=>this.apply(entry,m)).catch(()=>this.rules.broadcast({type:'living-error',playerId:entry.player.id,message:'生活の状態を保存できませんでした。もう一度操作してください'}));this.rules.onAsyncWork(this.queue);return this.queue;}
 async persist(record){const key=record.index+':'+record.itemId;this.rules.settingsQueue=this.rules.settingsQueue.then(async()=>{const living={...(this.rules.settings.living||{}),[key]:record},settings={...this.rules.settings,living};await this.rules.saveSettings(settings);this.rules.settings=settings;this.records=living;this.rules.broadcast({type:'living-state',record});});await this.rules.settingsQueue;this.rules.settingsQueue=this.rules.settingsQueue.catch(()=>{});}
 advance(run,now){const dt=Math.min(1,Math.max(0,(now-run.lastAt)/1000));run.lastAt=now;const elapsed=(now-run.startAt)/1000,required=Math.min(1.05,.35+elapsed*.003),effort=now-run.inputAt<800?run.effort:0;run.speed=Math.max(0,run.kind==='bike'?effort*7:effort*4);run.distance+=run.speed*dt;run.fatigue=Math.max(0,Math.min(1,run.fatigue+dt*(effort<required?.14:.015)));if(now-run.beatAt>run.period*1000){run.beatAt+=Math.floor((now-run.beatAt)/(run.period*1000))*run.period*1000;run.period=rhythm(run,now).period;}return run.fatigue>=1;}
 async finish(id,fallen=false){const run=this.runs.get(id);if(!run)return;this.runs.delete(id);const previous=this.records[run.key]||{},records={...(previous.records||{})},owner=run.profile;records[owner]={skin:run.skin,best:Math.max(records[owner]?.best||0,run.distance),total:(records[owner]?.total||0)+run.distance};const record={...previous,index:run.index,itemId:run.itemId,kind:'exercise',records,last:{skin:run.skin,distance:run.distance,at:Date.now()},rev:(previous.rev||0)+1};await this.persist(record);this.rules.broadcast({type:'living-exercise',playerId:id,ended:true,fallen,distance:run.distance});}
 async remove(id){await this.queue;await this.finish(id);}
 async apply(entry,m){const now=Date.now(),id=entry.player.id;if(m.action==='exercise-stop'){await this.finish(id);return;}const t=this.target(entry,m);if(!t){await this.finish(id);return;}const {kind,key,h,item,def}=t,previous=this.records[key]||{index:h.index,itemId:item.id,kind,rev:0};
  if(m.action==='exercise-start'&&kind==='exercise'){if([...this.runs.values()].some(r=>r.key===key))return;await this.finish(id);const run={key,index:h.index,itemId:item.id,kind:def.design,playerId:id,profile:entry.player.profile||'skin:'+entry.player.skin,skin:entry.player.skin,startAt:now,beatAt:now,period:2.6,lastAt:now,inputAt:now,effort:0,distance:0,fatigue:0,speed:0,lastJump:0};this.runs.set(id,run);this.rules.broadcast({type:'living-exercise',...run});return;}
  if(['exercise-input','exercise-jump'].includes(m.action)&&kind==='exercise'){const run=this.runs.get(id);if(!run||run.key!==key||now-(run.packetAt||0)<80)return;run.packetAt=now;if(this.advance(run,now)){await this.finish(id,true);return;}if(m.action==='exercise-input'){run.effort=Math.max(0,Math.min(1,Number(m.effort)||0));run.inputAt=now;}else if(now-run.lastJump>run.period*600){run.lastJump=now;const r=rhythm(run,now),success=Math.abs(r.phase-.78)<r.window;run.fatigue=Math.max(0,Math.min(1,run.fatigue+(success?-.22:.1)));run.success=success;}this.rules.broadcast({type:'living-exercise',...run});return;}
  if(now-(entry.lastLivingAt||0)<100)return;entry.lastLivingAt=now;const next={...previous,rev:previous.rev+1,at:now};let changed=false;
  if(kind==='paint'&&m.action==='paint'&&Array.isArray(m.points)&&m.points.length>0&&m.points.length<=48){const points=m.points.filter(p=>Array.isArray(p)&&p.length===2&&p.every(n=>Number.isFinite(n)&&n>=0&&n<=1));if(points.length!==m.points.length)return;const strokes=previous.strokes||[];if(strokes.reduce((n,s)=>n+s.length,0)+points.length>16000){this.rules.broadcast({type:'living-error',playerId:id,message:'このキャンバスは描画上限です。新しいキャンバスを置いてください'});return;}next.strokes=[...strokes,points];changed=true;}
  if(kind==='chess'&&m.action==='chess'){if(m.rev!==previous.rev)return;const chess=chessMove(previous.chess||chessStart(),m.from,m.to);if(chess){next.chess=chess;changed=true;}}
  if(kind==='tv'&&['power','channel'].includes(m.action)){next.enabled=m.action==='power'?!previous.enabled:!!previous.enabled;next.channel=((previous.channel||0)+(m.action==='channel'?Math.sign(m.step||1):0)+8)%8;changed=true;}
  if(['laundry','microwave','bath','trash'].includes(kind)){
   if(m.action==='open'&&!(previous.endAt>now)){next.open=!previous.open;changed=true;}
   if(m.action==='load'&&previous.open){next.loaded=!previous.loaded;changed=true;}
   if(m.action==='start'&&!(previous.endAt>now)&&(!previous.open||kind==='bath')&&(previous.loaded||kind==='bath')){next.open=false;next.startAt=now;next.endAt=now+(kind==='laundry'?45000:kind==='bath'?20000:15000);changed=true;}
   if(m.action==='empty'&&kind==='trash'){next.loaded=false;next.open=true;changed=true;}
  }
  if(['sewing','basketball','globe','horse','toy','object'].includes(kind)&&m.action==='use'){next.uses=(previous.uses||0)+1;next.phase=(previous.phase||0)+1;if(kind==='basketball'){next.scored=(previous.scored||0)+(Number.isFinite(m.power)&&Math.abs(m.power-.75)<.18?1:0);}if(kind==='sewing')next.stitches=(previous.stitches||0)+12;changed=true;}
  if(changed){await this.persist(next);this.rules.broadcast({type:'living-motion',index:h.index,itemId:item.id,playerId:id,kind,at:now});}
 }
}
